styling.global_css:
@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/geist";

@custom-variant dark (&:is(.dark *));

@theme inline {
	--font-heading: var(--font-sans);
	--font-sans: 'Geist Variable', sans-serif;
	--color-ring: var(--ring);
	--color-input: var(--input);
	--color-border: var(--border);
	--color-destructive: var(--destructive);
	--color-accent-foreground: var(--accent-foreground);
	--color-accent: var(--accent);
	--color-muted-foreground: var(--muted-foreground);
	--color-muted: var(--muted);
	--color-secondary-foreground: var(--secondary-foreground);
	--color-secondary: var(--secondary);
	--color-primary-foreground: var(--primary-foreground);
	--color-primary: var(--primary);
	--color-popover-foreground: var(--popover-foreground);
	--color-popover: var(--popover);
	--color-card-foreground: var(--card-foreground);
	--color-card: var(--card);
	--color-foreground: var(--foreground);
	--color-background: var(--background);
	--radius-lg: var(--radius);
}

:root {
	--background: oklch(0.1 0.01 250);
	--foreground: oklch(0.98 0.01 250);
	--card: oklch(0.15 0.02 250);
	--card-foreground: oklch(0.98 0.01 250);
	--popover: oklch(0.15 0.02 250);
	--popover-foreground: oklch(0.98 0.01 250);
	--primary: oklch(0.55 0.25 25);
	--primary-foreground: oklch(1 0 0);
	--secondary: oklch(0.35 0.15 250);
	--secondary-foreground: oklch(0.98 0.01 250);
	--muted: oklch(0.25 0.02 250);
	--muted-foreground: oklch(0.7 0.02 250);
	--accent: oklch(0.65 0.2 25);
	--accent-foreground: oklch(1 0 0);
	--destructive: oklch(0.6 0.2 25);
	--border: oklch(0.25 0.02 250 / 0.2);
	--input: oklch(0.25 0.02 250);
	--ring: oklch(0.55 0.25 25);
	--radius: 0.75rem;
}

@layer base {
	* {
		@apply border-border outline-ring/50;
	}
	body {
		@apply bg-background text-foreground antialiased selection:bg-primary selection:text-primary-foreground overflow-x-hidden;
        background-image: radial-gradient(circle at 50% 50%, oklch(0.15 0.03 250 / 0.5) 0%, transparent 80%);
	}
    /* Web Pattern Overlay */
    body::before {
        content: '';
        position: fixed;
        top: 0; left: 0; width: 100%; height: 100%;
        background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M30 0 L60 30 L30 60 L0 30 Z' fill='none' stroke='rgba(255,255,255,0.03)' stroke-width='1'/%3E%3C/svg%3E");
        pointer-events: none;
        z-index: -1;
    }
}

.web-marquee {
    white-space: nowrap;
    animation: scroll 40s linear infinite;
}

@keyframes scroll {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
}
